#!/usr/bin/env python3
"""End-to-end check of the built site in Chrome with a fake Supabase (tests/mock-supabase.js) seeded from the
migration export. run: /workspace/.tools-venv/bin/python tests/e2e.py   (needs tests/serve.py on :8097)"""
import json, sys
from pathlib import Path
from playwright.sync_api import sync_playwright
ROOT = Path(__file__).resolve().parents[1]; EXP = ROOT / "migration" / "export"; SHOTS = ROOT / "tests" / "shots"; SHOTS.mkdir(exist_ok=True)
URL = "http://127.0.0.1:8097"
seed = {"profile": json.loads((EXP / "profile.json").read_text()), "docs": {f.stem: json.loads(f.read_text()) for f in (EXP / "docs").glob("*.json")}}
mock = (ROOT / "tests" / "mock-supabase.js").read_text()
fails = []
def check(c, m): print(("PASS " if c else "FAIL ") + m); (None if c else fails.append(m))
with sync_playwright() as p:
    b = p.chromium.launch(executable_path="/usr/bin/google-chrome", args=["--no-sandbox"])
    ctx = b.new_context(viewport={"width": 390, "height": 844}, device_scale_factor=2, is_mobile=True, has_touch=True, service_workers="block")
    ctx.add_init_script("window.MOCK_SEED = " + json.dumps(seed) + ";")
    ctx.route("**/vendor/supabase.js*", lambda r: r.fulfill(body=mock, content_type="text/javascript"))
    ctx.route("https://fonts.googleapis.com/**", lambda r: r.abort()); ctx.route("https://fonts.gstatic.com/**", lambda r: r.abort())
    page = ctx.new_page(); errs = []
    page.on("dialog", lambda d: d.accept())
    page.on("response", lambda r: errs.append("404 " + r.url) if r.status == 404 else None)
    page.on("pageerror", lambda e: errs.append(str(e)))
    page.on("console", lambda m: errs.append(m.text) if m.type == "error" and "favicon" not in m.text and "ERR_FAILED" not in m.text else None)
    page.goto(URL + "/#journal"); page.wait_for_url("**/login**", timeout=8000)
    check("/login" in page.url and "next=" in page.url, "signed-out visit goes to the login page (keeps where you were going)")
    page.fill("#un", "natalie"); page.fill("#pw", "wrong-pass"); page.click("#go"); page.wait_for_timeout(400)
    check("don’t match" in page.inner_text("#err"), "wrong password refused")
    page.fill("#pw", "test-password-1"); page.click("#go"); page.wait_for_url("**/#journal", timeout=8000); page.wait_for_timeout(1500)
    check(page.text_content(".header .eyebrow").startswith("Natalie"), "signed in as Natalie; header says Natalie’s Tarot")
    page.screenshot(path=str(SHOTS / "01-journal.png"))
    # main draw flow: who-is-it-for sheet → flip → "For you" pop-up with the full reading; then a 3-card spread
    page.evaluate("location.hash='today'"); page.wait_for_timeout(600)
    page.click("#drawBtn"); page.wait_for_timeout(500)
    check(page.is_visible("#whoSheet"), "draw asks “Who is this reading for?” first")
    page.screenshot(path=str(SHOTS / "02-who-sheet.png"))
    page.click("#whoSheet [data-me]"); page.wait_for_timeout(1200)
    page.click("button.flip[data-i='0']"); page.wait_for_timeout(1500)
    check(page.is_visible("#modal") and "for you" in page.text_content("#modal").lower(), "one card → “For you, N” pop-up with an individual reading")
    page.screenshot(path=str(SHOTS / "03-for-you-popup.png"))
    page.keyboard.press("Escape"); page.wait_for_timeout(300)
    if page.is_visible("#modal"): page.evaluate("document.getElementById('modal').hidden = true")
    page.click("[data-count='3']"); page.wait_for_timeout(400)
    if page.is_visible("#drawBtn"): page.click("#drawBtn"); page.wait_for_timeout(400)
    if page.is_visible("#whoSheet"): page.click("#whoSheet [data-me]"); page.wait_for_timeout(1000)
    for i in range(3):
        if page.is_visible(f"button.flip[data-i='{i}']:not(.flipped)"): page.click(f"button.flip[data-i='{i}']"); page.wait_for_timeout(700)
    page.wait_for_timeout(1200); txt = page.text_content("body")
    check(page.locator("button.flip.flipped").count() >= 3, "3-card spread: all cards flip with pictures")
    check(any(k in txt for k in ("Together", "together", "Combined", "combined", "whole spread")), "combined reading appears once all cards are flipped")
    page.screenshot(path=str(SHOTS / "04-spread-reading.png"), full_page=True)
    api = lambda path, body=None: page.evaluate("""async ([p, b]) => { const r = await fetch(p, b ? {method:'POST', headers:{'Content-Type':'application/json'}, body: JSON.stringify(b)} : {});
        const ct = r.headers.get('content-type') || ''; return { status: r.status, ct, data: ct.includes('json') ? await r.json() : (await r.blob()).size }; }""", [path, body])
    st = api("/auth/status")["data"]; check(st["owner"] and st["birth"] == "1997-03-07", "auth/status: owner + birth")
    check(len(api("/api/entries")["data"]) == len(seed["docs"]["entries"]), "journal entries migrated")
    gs = api("/api/guests")["data"]; nick = next(g for g in gs if g["name"] == "Nick")
    check((nick.get("birth") or {}).get("date") == "1996-01-25", "Nick's birthday 1996-01-25 migrated")
    check(len(api("/api/cards")["data"]) == 78, "78 cards with knowledge")
    a = api("/api/astro/today")["data"]; check(a.get("big_three", {}).get("Ascendant") == "Scorpio" and a["natal"]["Sun"]["sign"] == "Pisces", "Natalie's horoscope: Pisces Sun, Scorpio rising (full chart)")
    mo = api("/api/moon")["data"]; check(mo.get("phase") and mo.get("sign"), "moon phase today: %s in %s" % (mo.get("phase"), mo.get("sign")))
    h = api(f"/api/guests/{nick['id']}/horoscope"); check(h["status"] == 400 and h["data"].get("needs") == "birth", "Nick horoscope asks for a birthplace (same as before)")
    r = api(f"/api/guests/{nick['id']}/profile", {"birth_date": "1996-01-25", "birth_place": "Seattle, Washington", "birth_name": "Nick"})
    check(r["data"]["guest"].get("sun_sign") == "Aquarius", "guest profile save → Aquarius Sun")
    h = api(f"/api/guests/{nick['id']}/horoscope"); check(h["status"] == 200 and h["data"]["guest"] == "Nick", "guest horoscope with birthplace works")
    e = api("/api/entries", {"cards": [{"id": "ar00", "orientation": "upright"}, {"id": "ar01", "orientation": "reversed"}, {"id": "ar02", "orientation": "upright"}], "spreadLabels": ["Past", "Present", "Future"], "note": "test"})
    check(e["status"] == 200 and len(e["data"]["added"]) == 3 and e["data"]["outbox"]["status"] == "pending_astro", "save my 3-card draw → journal + outbox for Astro")
    e2 = api("/api/entries", {"cards": [{"id": "ar00", "orientation": "upright"}]}); check(e2["data"]["skipped"] == ["The Fool"], "duplicate card skipped")
    bad = api("/api/entries", {"cards": [{"id": "zz99", "orientation": "upright"}]}); check(bad["status"] == 400, "unknown card → 400")
    png1x1 = "data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mP8z8BQDwAEhQGAhKmMIQAAAABJRU5ErkJggg=="
    gr = api(f"/api/guests/{nick['id']}/readings", {"cards": [{"id": "ar10", "orientation": "upright", "position": "Past"}], "spread": "Past / Present / Future", "question": "Work?", "photos": [{"data": png1x1}],
             "generated_reading": {"summary": "All together...", "cards": [{"label": "Past", "name": "Wheel of Fortune", "orientation": "upright", "core": "Turning point."}]}})
    check(gr["status"] == 200 and gr["data"]["reading"]["photos"][0].startswith("uploads/guests/nick/"), "guest reading saved with photo in private storage")
    rid = gr["data"]["reading"]["id"]
    check(len(next(g for g in api("/api/guests")["data"] if g["name"] == "Nick")["readings"]) == 2, "Nick now has 2 readings")
    s1 = api(f"/api/guests/{nick['id']}/readings/{rid}/share.png", {"include": {"reading": True}}); check(s1["status"] == 200 and s1["ct"] == "image/png" and s1["data"] > 20000, "share guest reading as image (%s bytes)" % s1["data"])
    s2 = api(f"/api/guests/{nick['id']}/readings/{rid}/share.pdf", {"include": {"reading": True}}); check(s2["status"] == 200 and s2["ct"] == "application/pdf" and s2["data"] > 20000, "share guest reading as PDF (%s bytes)" % s2["data"])
    ins = api(f"/api/guests/{nick['id']}/insights", {"kind": "numerology", "text": "Life path 6"}); check(ins["status"] == 200, "save guest numerology insight")
    pr = api("/api/practice/review", {"card": "ar00", "rating": "knew"}); check(pr["data"]["review"]["box"] >= 2, "practice flashcard review (Leitner)")
    check(api("/api/practice/pull", {"cards": [{"id": "ar03", "orientation": "upright"}]})["status"] == 200, "practice pull")
    check(api("/api/practice/reading", {"spreadId": "ppf", "cards": [{"id": "ar04", "orientation": "upright", "note": "n"}]})["status"] == 200, "practice reading")
    check(api("/api/practice/quiz", {"score": 4, "total": 5})["status"] == 200 and api("/api/practice/lesson", {"id": "intro"})["status"] == 200 and api("/api/practice/day", {})["status"] == 200, "quiz / lesson / daily")
    ph = api("/api/photos", {"photos": [{"data": png1x1}], "note": "my spread photo"}); check(ph["data"]["outbox"]["status"] == "needs_identification", "photo of my own draw → outbox")
    oid = ph["data"]["outbox"]["id"]; res = api(f"/api/outbox/{oid}/resolve", {"cards": [{"name": "The Star", "orientation": "upright"}], "reading": "Hope."})
    check(res["status"] == 200 and res["data"]["record"]["status"] == "resolved", "bot resolves the photo into the journal")
    gaps = api("/api/gaps")["data"]; og = next((g for g in gaps if g.get("status") == "open"), None)
    if og: check(api("/api/gaps/resolve", {"id": og["id"], "orientation": "unknown"})["status"] == 200, "gap answered “I don’t remember”")
    me = api("/social/me")["data"]; check(me["user"]["username"] == "natalie" and me["invite"], "friends: my profile + invite link")
    check(api("/social/share", {"kind": "guest_reading", "ref": rid, "title": "A reading", "payload": {"x": 1}})["status"] == 200, "share a reading with friends")
    # photos show through signed links
    print("before reload:", len(next(g for g in api("/api/guests")["data"] if g["name"] == "Nick")["readings"]))
    page.goto(URL + "/#guests"); page.reload(); page.wait_for_timeout(1500)
    print("after reload:", len(next(g for g in api("/api/guests")["data"] if g["name"] == "Nick")["readings"]))
    page.wait_for_timeout(1500); print("profile:", page.inner_text("#profile")[:160].replace("\n"," | "))
    check(page.evaluate("() => [...document.querySelectorAll('img')].some(i => i.src.startsWith('data:image/png') || i.src.includes('/storage/v1/object/sign/'))"), "private photo shows through a signed link")
    page.screenshot(path=str(SHOTS / "05-guest-nick.png"), full_page=True)
    for tab in ["today", "journal", "guests", "cards", "practice", "astro", "meditate", "friends", "compat"]:
        page.evaluate(f"location.hash = '{tab}'"); page.wait_for_timeout(900); page.screenshot(path=str(SHOTS / f"tab-{tab}.png"))
    page.evaluate("location.hash='compat'"); page.wait_for_timeout(1200)
    check(page.locator("#compatBody").is_visible(), "compatibility tab opens")
    page.locator("#compatBody button", has_text="New reading").first.click(); page.wait_for_timeout(800)
    t = page.inner_text("#compatBody"); check("Natalie" in t and "from your profile" in t, "compat: Person 1 prefilled from her profile")
    page.screenshot(path=str(SHOTS / "tab-compat-form.png"))
    check(page.locator("#tjGear").count() == 1, "Settings gear in the header")
    page.evaluate("location.hash='journal'"); page.wait_for_timeout(800)
    ok_imgs = page.evaluate("() => [...document.querySelectorAll('img')].filter(i => i.complete && i.naturalWidth > 0 && /deck-|journal-img/.test(i.src)).length")
    check(ok_imgs > 0, f"card pictures load ({ok_imgs} on the journal tab)")
    print("errors:", errs[:8])
    check(not [x for x in errs if "Failed to load resource" not in x and not x.startswith("404 " + URL + "/uploads/guests/nick/ph-")], "no script errors in the console (only Nick's 3 old photos, which the test fake doesn't hold)")
    # second user: sign up, befriend via invite, see the share
    page.click("#logoutForm button") if page.is_visible("#logoutForm button") else page.evaluate("document.getElementById('logoutForm').requestSubmit()")
    page.wait_for_url("**/login**", timeout=8000)
    page.goto(URL + "/signup?next=" + "%2Finvite%2Finv-natalie".replace("%2Finvite%2Finv-natalie", "%2F%23friends%3Finvite%3Dinv-natalie"))
    page.fill("#dn", "Sam"); page.fill("#un", "sam_1"); page.fill("#pw", "longpassword"); page.fill("#pw2", "longpassword"); page.fill("#bd", "1990-06-15"); page.click("#go")
    page.wait_for_timeout(2500)
    page.click("#frInvAccept"); page.wait_for_timeout(1200)
    check("natalie" in page.inner_text("#friendsBody").lower(), "invite screen accepted on the Friends tab")
    st2 = api("/auth/status")["data"]; check(st2["user"] == "sam_1" and not st2["owner"], "new person can sign up and gets their own private deck")
    check(api("/api/guests")["data"] == [], "new account can't see Natalie's guests")
    feed = api("/social/feed")["data"]; check(any(x["title"] == "A reading" for x in feed), "invite link made them friends; they see only what she shared")
    a2 = api("/api/astro/today")["data"]; check(a2["natal"]["Sun"]["sign"] == "Gemini", "new user's own horoscope from sign-up birthday")
    page.screenshot(path=str(SHOTS / "06-friend-view.png"))
    b.close()
print("\n%d FAILED: %s" % (len(fails), fails) if fails else "\nall e2e checks passed"); sys.exit(1 if fails else 0)
